import numpy as np, pandas as pd
from lmfit.models import LorentzianModel, PolynomialModel
from scipy.ndimage import median_filter
d = pd.read_csv('spectrum.csv')
x = np.arange(60, 723, 1.0)
main = {'155': (155.3, 3.2), '299': (299.0, 4.5), '353': (352.8, 4.6), '354b': (354.8, 4.0)}
controls = {'c450': (450.0, 4.5), 'c520': (520.0, 4.5), 'c600': (600.0, 4.5), 'c690': (690.0, 4.5)}

def fit(s, bands):
    mod = PolynomialModel(degree=3, prefix='bg_')
    pars = mod.make_params(c0=400, c1=0, c2=0, c3=0)
    for n, (c, w) in bands.items():
        L = LorentzianModel(prefix=f'b{n}_')
        pars.update(L.make_params(center=c, sigma=w / 2, amplitude=500))
        pars[f'b{n}_center'].set(vary=False); pars[f'b{n}_sigma'].set(vary=False)
        mod = mod + L
    return mod.fit(s, pars, x=x)

for cfg in ['parallel', 'crossed']:
    res_list = {k: [] for k in list(controls)}
    for ang in range(0, 180, 10):
        s = d[(d.config == cfg) & (d.angle_deg == ang)].set_index('shift_cm1').intensity.loc[x].values
        bands = {**controls, **{k: v for k, v in main.items() if not (cfg == 'parallel' and k == '354b')}}
        r = fit(s, bands)
        for k in controls:
            res_list[k].append(r.params[f'b{k}_amplitude'].value)
    print(cfg, 'control amplitudes: mean / std over 18 angles')
    for k, v in res_list.items():
        v = np.array(v); print(f'   {k}: mean={v.mean():7.0f}  std={v.std(ddof=1):6.0f}  (lmfit stderr ~1200)')
EOF
