import numpy as np, pandas as pd
from lmfit.models import LorentzianModel, PolynomialModel
d = pd.read_csv('spectrum.csv')
x = np.arange(60, 723, 1.0)
main = {'155': (155.3, 3.2), '299': (299.0, 4.5), '353': (352.8, 4.6)}
weak_par = [102, 259, 532, 594, 632, 210, 240, 380, 440, 475, 550, 700]
weak_cro = [161, 222, 239, 354.8, 384, 426, 639, 102, 259, 532, 594, 632]
def fit(s, bands):
    mod = PolynomialModel(degree=3, prefix='bg_')
    pars = mod.make_params(c0=400, c1=0, c2=0, c3=0)
    for n, (c, w) in bands.items():
        L = LorentzianModel(prefix=f'b{n}_')
        pars.update(L.make_params(center=c, sigma=w / 2, amplitude=500))
        pars[f'b{n}_center'].set(vary=False); pars[f'b{n}_sigma'].set(vary=False)
        mod = mod + L
    return mod.fit(s, pars, x=x)
for cfg, weak in [('parallel', weak_par), ('crossed', weak_cro)]:
    bands = dict(main)
    if cfg == 'crossed': bands['354b'] = (354.8, 4.0)
    cand = {f'w{int(round(c))}': (c, 4.5) for c in weak}
    amps = {k: [] for k in cand}
    for ang in range(0, 180, 10):
        s = d[(d.config == cfg) & (d.angle_deg == ang)].set_index('shift_cm1').intensity.loc[x].values
        r = fit(s, {**bands, **cand})
        for k in cand: amps[k].append(r.params[f'bw{k[1:]}_amplitude'].value)
    print(cfg)
    for k, v in amps.items():
        v = np.array(v); m = v.mean(); se = v.std(ddof=1) / np.sqrt(len(v))
        print(f'   {k[1:]:>5s}: mean amp={m:7.0f} +- {se:4.0f}  (z={m/se:5.1f})')
EOF
